-- Copia exacta de los productos actuales de inventarioReal.js.
-- Ejecutar completo DESPUES de 01_crear_tablas.sql. No sobrescribe datos.
begin;
set local standard_conforming_strings = on;
lock table public.categories, public.products in exclusive mode;

do $$
begin
  if exists (select 1 from public.categories) or exists (select 1 from public.products) then
    raise exception 'Ya existen datos. No se ha importado nada. Revisa las tablas antes de continuar.';
  end if;
end;
$$;



do $$
begin
  if (select count(*) from public.categories) <> 20
    or (select count(*) from public.products) <> 173
    or (select sum(stock) from public.products) <> 1169
    or (select sum(stock * price) from public.products) <> 618895.00 then
    raise exception 'Los totales no coinciden con la copia local. La importacion se cancela.';
  end if;
end;
$$;

select setval(pg_get_serial_sequence('public.categories', 'id'), (select max(id) from public.categories));
select setval(pg_get_serial_sequence('public.products', 'id'), (select max(id) from public.products));
commit;

select
  (select count(*) from public.categories) as categorias,
  count(*) as productos,
  sum(stock) as unidades,
  sum(stock * price) as valor_inventario
from public.products;
